def parse_molecule(s):
    atom_counts = {}
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        if not char.isupper():
            raise ValueError(f"Unexpected character at index {i}: {char}")

        atom = char
        count = 0

        # Check for number
        j = i + 1
        while j < n and s[j].isdigit():
            count = count * 10 + int(s[j])
            j += 1

        if count == 0:
            count = 1

        atom_counts[atom] = atom_counts.get(atom, 0) + count
        i = j

    return atom_counts

